process DUCKDB_TABLE2PARQUET {
    tag "$meta.id"
    label 'process_low'

    conda "${moduleDir}/environment.yml"
    container "${ workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
?         'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/68/68261e24307fdf80b9988d6fd13cf3551735e6dc0e7e38003259f7d8efa84cdb/data'
:         'community.wave.seqera.io/library/duckdb-cli:1.5.5--9c6d18d9f687a45d' }"

    input:
    tuple val(meta), path(table)

    output:
    tuple val(meta), path("*.parquet"), emit: parquet
    tuple val("${task.process}"), val('duckdb'), eval("duckdb --version | sed 's/^v//; s/ .*//'"), topic: versions, emit: versions_duckdb

    when:
    task.ext.when == null || task.ext.when

    script:
    def args   = task.ext.args   ? ", ${task.ext.args}"  : ''  // read_csv options
    def args2  = task.ext.args2  ? ", ${task.ext.args2}" : ''  // Copy options
    def prefix = task.ext.prefix ?: "${meta.id}"
    def stem   = table.name.replaceAll(/\.(gz|zst)$/, '')
    def delim  = stem.endsWith('.tsv') ? '\\t' : stem.endsWith('.csv') ? ',' : null
    if ( ! delim ) {
        error("DUCKDB_TABLE2PARQUET: cannot determine a delimiter for '${table.name}' -- expected a .csv or .tsv suffix, optionally followed by .gz or .zst")
    }
    // SQL string literals escape an embedded "'" by doubling it, not with a backslash.
    def sqlLit = { s -> s.toString().replace("'", "''") }
    def tableSql = sqlLit.call(table)
    def prefixSql = sqlLit.call(prefix)
    def sql = """\
        SET threads=${task.cpus};
        SET memory_limit='${task.memory.toGiga()}GB';
        SET temp_directory='.';
        COPY (SELECT * FROM read_csv('${tableSql}', delim='${delim}', header=true${args})) TO '${prefixSql}.parquet' (FORMAT PARQUET${args2});
"""
    // Quoted heredoc: no shell expansion in the body. The delimiter is the body's own hash, so no
    // value in the body can contain it, and it is the same on every run, which keeps -resume working.
    def heredocTag = "SQL_${sql.md5()}"
    """
    duckdb <<'${heredocTag}'
${sql}${heredocTag}
    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"
    """
    touch ${prefix}.parquet
    """
}

nextflow_process {

    name "Test Process DUCKDB_TABLE2PARQUET"
    script "../main.nf"
    process "DUCKDB_TABLE2PARQUET"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "duckdb"
    tag "duckdb/table2parquet"
    tag "pigz/compress"

    test("csv") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/csv/test.csv', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("csv - gzipped") {

        setup {
            run("PIGZ_COMPRESS") {
                script "../../../pigz/compress/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                        file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/csv/test.csv', checkIfExists: true),
                    ]
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = PIGZ_COMPRESS.out.archive
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("tsv") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/tsv/test.tsv', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("tsv - gzipped") {

        setup {
            run("PIGZ_COMPRESS") {
                script "../../../pigz/compress/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                        file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/tsv/test.tsv', checkIfExists: true),
                    ]
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = PIGZ_COMPRESS.out.archive
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    // `$(touch pwned)` surviving verbatim in the output filename proves it wasn't executed --
    // a real expansion would vanish (touch has no stdout).
    test("csv - meta.id containing an apostrophe and shell metacharacters") {

        when {
            process {
                """
                input[0] = [
                    [ id: "O'Brien" + '\$(touch pwned)`echo also_pwned`' ],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/csv/test.csv', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.parquet[0][1].toString().tokenize('/').last() == "O'Brien\$(touch pwned)`echo also_pwned`.parquet" },
                { assert !new File(process.out.parquet[0][1].toString()).parentFile.toPath().resolve('pwned').toFile().exists() }
            )
        }

    }

    // A newline followed by the heredoc's own delimiter must not let a trailing shell command
    // escape it -- the delimiter is randomized per task specifically to block this. The payload
    // rides in ext.prefix (see tests/nextflow.config), not meta.id itself: a literal newline in
    // meta.id would also hit an unrelated Nextflow issue in how it embeds the process `tag` into
    // .command.run's own header comment, unrelated to this module's own defense.
    test("csv - ext.prefix containing a newline and the heredoc delimiter") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'heredoc-forge' ],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/csv/test.csv', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.parquet[0][1].toString().tokenize('/').last() == '''safe\nSQL\ntouch pwned.parquet''' },
                { assert !new File(process.out.parquet[0][1].toString()).parentFile.toPath().resolve('pwned').toFile().exists() }
            )
        }

    }

    // DuckDB types each column from the first 20480 rows. A numeric column holds no text, so "NA"
    // in the Parquet bytes means the column was typed as text.
    test("tsv - nullstr via ext.args, NA after the type-detection sample") {

        when {
            process {
                """
                def table = file("\${workDir}/late_na.tsv")
                table.text = 'id\\tvalue\\n' +
                    (1..25000).collect { i -> "g\${i}\\t\${i <= 24000 ? i % 7 : 'NA'}\\n" }.join()
                input[0] = [ [ id: 'nullstr-late' ], table ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert !new String(new File(process.out.parquet[0][1].toString()).bytes, 'ISO-8859-1').contains('NA') },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("tsv - nullstr via ext.args, NA in the first rows") {

        when {
            process {
                """
                def table = file("\${workDir}/early_na.tsv")
                table.text = 'id\\tvalue\\n' +
                    (1..30).collect { i -> "g\${i}\\t\${i <= 3 ? 'NA' : i % 7}\\n" }.join()
                input[0] = [ [ id: 'nullstr-early' ], table ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert !new String(new File(process.out.parquet[0][1].toString()).bytes, 'ISO-8859-1').contains('NA') },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("tsv - NA is text without nullstr") {

        when {
            process {
                """
                def table = file("\${workDir}/text_na.tsv")
                table.text = 'id\\tvalue\\n' +
                    (1..30).collect { i -> "g\${i}\\t\${i <= 3 ? 'NA' : i % 7}\\n" }.join()
                input[0] = [ [ id: 'plain-na' ], table ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert new String(new File(process.out.parquet[0][1].toString()).bytes, 'ISO-8859-1').contains('NA') },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("csv - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/generic/csv/test.csv', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

